const DOUBLED = [...ICONS, ...ICONS];

export default function CodingIconsPopup({ children }: { children: ReactNode }) {
  const [open, setOpen] = useState(false);

  return (
    <span
      className="relative inline-block"
      onMouseEnter={() => setOpen(true)}
      onMouseLeave={() => setOpen(false)}
    >
      <button
        type="button"
        aria-expanded={open}
        onFocus={() => setOpen(true)}
        onBlur={() => setOpen(false)}
        className="cursor-help underline decoration-dotted underline-offset-4 transition hover:brightness-125 focus-visible:brightness-125"
      >
        {children}
      </button>

      <span
        aria-hidden={!open}
        className={`pointer-events-none absolute bottom-full left-1/2 z-30 mb-3 block w-[244px] -translate-x-1/2 origin-bottom transition duration-300 ease-out ${
          open
            ? "translate-y-0 rotate-[-1deg] scale-100 opacity-100"
            : "translate-y-3 rotate-0 scale-95 opacity-0"
        }`}
      >
        <span
          className="relative block overflow-hidden rounded-lg bg-white p-3 shadow-2xl ring-1 ring-black/10 dark:bg-zinc-900 dark:ring-white/15"
          style={{
            maskImage:
              "linear-gradient(to right, transparent, black 12%, black 88%, transparent)",
            WebkitMaskImage:
              "linear-gradient(to right, transparent, black 12%, black 88%, transparent)",
          }}
        >
          <span
            className="flex w-max gap-3.5"
            style={{
              animation: open ? "coding-marquee 16s linear infinite" : "none",
            }}
          >
            {DOUBLED.map((icon, i) => (
              <span
                key={i}
                title={icon.name}
                className="flex w-16 flex-none flex-col items-center gap-1"
              >
                <span
                  className="flex h-10 w-10 items-center justify-center rounded-lg"
                  style={{ backgroundColor: icon.color }}
                >
                  <svg
                    viewBox={icon.viewBox}
                    className="h-6 w-6 fill-white text-white"
                    aria-hidden
                  >
                    {icon.path}
                  </svg>
                </span>
                <span className="text-[9px] font-medium text-zinc-600 dark:text-zinc-300">
                  {icon.name}
                </span>
              </span>
            ))}
          </span>
        </span>
      </span>
    </span>
  );
}
